{
  "name": "search_in_file",
  "description": "Search ONE file (PDF, DOCX or TXT) for a keyword, case-insensitively, and return each match with its line number and surrounding context. total_matches == 0 means the keyword is absent. To search many resumes, call this once per file (calls can be made in parallel).",
  "parameters": {
    "type": "object",
    "properties": {
      "filepath": {
        "type": "string",
        "description": "Path relative to the project root."
      },
      "keyword": {
        "type": "string",
        "description": "Literal text to find (not a regex), e.g. 'Python'."
      },
      "context_chars": {
        "type": "integer",
        "minimum": 0,
        "description": "Characters of context on each side of a match (default 80)."
      },
      "max_matches": {
        "type": "integer",
        "minimum": 1,
        "description": "Maximum matches to return (default 20); total_matches still reports the true count."
      },
      "whole_word": {
        "type": "boolean",
        "description": "Match whole words only, so 'Java' does not match 'JavaScript' (default false)."
      }
    },
    "required": [
      "filepath",
      "keyword"
    ],
    "additionalProperties": false
  }
}
